def json_inspector(text: str, indent: int = 2) -> dict:
    """Format, validate and inspect JSON text."""
    import json
    try:
        data = json.loads(text)
        return {
            'success': True,
            'valid': True,
            'formatted': json.dumps(data, indent=indent),
            'type': type(data).__name__,
            'keys': list(data.keys()) if isinstance(data, dict) else len(data),
        }
    except Exception as e:
        return {'success': False, 'valid': False, 'error': str(e)}

def hash_calculator(text: str = '', algorithm: str = 'sha256') -> dict:
    """Compute cryptographic hash of a given string."""
    import hashlib
    algo = algorithm.lower().strip()
    if algo not in hashlib.algorithms_available:
        return {'success': False, 'error': f'Unsupported algorithm: {algo}'}
    h = hashlib.new(algo)
    h.update(text.encode('utf-8'))
    return {'success': True, 'algorithm': algo, 'digest': h.hexdigest(), 'length': len(text)}

def regex_tester(pattern: str, text: str) -> dict:
    """Test regex pattern and return matches."""
    import re
    try:
        compiled = re.compile(pattern)
        matches = [m.group(0) for m in compiled.finditer(text)]
        return {'success': True, 'pattern': pattern, 'match_count': len(matches), 'matches': matches[:50]}
    except Exception as e:
        return {'success': False, 'error': str(e)}

def currency_converter(amount: float, from_curr: str = 'USD', to_curr: str = 'EUR') -> dict:
    """Convert currency using standard baseline rates."""
    rates_to_usd = {'USD': 1.0, 'EUR': 0.92, 'GBP': 0.79, 'JPY': 154.5, 'EGP': 49.2, 'CAD': 1.38}
    f = from_curr.upper()
    t = to_curr.upper()
    if f not in rates_to_usd or t not in rates_to_usd:
        return {'success': False, 'error': f'Unsupported currency pair {f}->{t}'}
    usd_val = amount / rates_to_usd[f]
    res = round(usd_val * rates_to_usd[t], 4)
    return {'success': True, 'amount': amount, 'from': f, 'to': t, 'result': res}

