def analyze_metrics(path: str = '.') -> dict:
    import os
    total_lines = 0
    files = 0
    for root, _, fnames in os.walk(path):
        for f in fnames:
            if f.endswith('.py'):
                files += 1
                try:
                    with open(os.path.join(root, f), 'r', encoding='utf-8', errors='ignore') as fp:
                        total_lines += sum(1 for _ in fp)
                except Exception:
                    pass
    return {'success': True, 'python_files': files, 'total_lines': total_lines}

"""dependency_guard plugin main.py"""
def check_deps(path: str = 'requirements.txt') -> dict:
    import os
    if not os.path.exists(path):
        return {'success': True, 'message': 'No requirements.txt found', 'unpinned': []}
    unpinned = []
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith('#') and '==' not in line and '>=' not in line:
                unpinned.append(line)
    return {'success': True, 'unpinned_count': len(unpinned), 'unpinned': unpinned}
